const fs = require('fs');
const raw = fs.readFileSync('data/steam.csv', 'utf8').split(/\r?\n/).filter(Boolean);
const header = raw[0].split(',');
// robust-ish CSV split (dataset uses ; inside fields, so commas are safe delimiters except names may have commas)
function parse(line){
  const out=[]; let cur=''; let q=false;
  for(const ch of line){
    if(ch==='"'){q=!q;continue;}
    if(ch===','&&!q){out.push(cur);cur='';continue;}
    cur+=ch;
  }
  out.push(cur); return out;
}
const idx = Object.fromEntries(header.map((h,i)=>[h,i]));
const ownerMid = s => { const [a,b]=s.split('-').map(Number); return (a+b)/2; };
const rows = raw.slice(1).map(parse).filter(r=>r.length===header.length).map(r=>{
  const pos=+r[idx.positive_ratings], neg=+r[idx.negative_ratings];
  const owners=ownerMid(r[idx.owners]);
  const price=+r[idx.price];
  return {
    name:r[idx.name],
    pos, neg,
    total: pos+neg,
    ratio: (pos+neg)>0 ? pos/(pos+neg) : 0,
    owners,
    price,
    revenue: owners*price,
    playtime:+r[idx.average_playtime],
  };
});
console.log('parsed rows:', rows.length);

function topN(arr,key,n=10,filter=x=>true){
  return arr.filter(filter).slice().sort((a,b)=>b[key]-a[key]).slice(0,n);
}
const show = (label, list) => {
  console.log('\n== '+label+' ==');
  list.forEach((r,i)=>console.log(`${i+1}. ${r.name.slice(0,32).padEnd(32)} ratio=${r.ratio.toFixed(3)} pos=${r.pos} owners=${r.owners} rev=${Math.round(r.revenue)} ply=${r.playtime}`));
};

// Definition A: popularity (estimated owners)
show('A) Most OWNED (reach)', topN(rows,'owners'));
// Definition B: critical reception (positive ratio), with credibility threshold
show('B) Highest POSITIVE RATIO (>=500 reviews)', topN(rows,'ratio',10,r=>r.total>=500));
// Definition C: commercial (estimated revenue)
show('C) Highest ESTIMATED REVENUE', topN(rows,'revenue'));
// Definition D: engagement (avg playtime), threshold owners
show('D) Highest AVG PLAYTIME (>=100k owners)', topN(rows,'playtime',10,r=>r.owners>=100000));

// Overlap: how much do the top-100 sets agree?
function topSet(key,n,filter=x=>true){return new Set(rows.filter(filter).slice().sort((a,b)=>b[key]-a[key]).slice(0,n).map(r=>r.name));}
const N=100;
const A=topSet('owners',N), B=topSet('ratio',N,r=>r.total>=500), C=topSet('revenue',N), D=topSet('playtime',N,r=>r.owners>=100000);
const inter=(x,y)=>[...x].filter(v=>y.has(v)).length;
console.log('\n== Overlap of TOP-'+N+' sets (out of '+N+') ==');
console.log('Owners ∩ Ratio   :', inter(A,B));
console.log('Owners ∩ Revenue :', inter(A,C));
console.log('Owners ∩ Playtime:', inter(A,D));
console.log('Ratio  ∩ Revenue :', inter(B,C));
console.log('Ratio  ∩ Playtime:', inter(B,D));
console.log('Revenue∩ Playtime:', inter(C,D));

// free games count among top owners
const freeTopOwners = [...A].filter(name=>{const r=rows.find(x=>x.name===name); return r && r.price===0;}).length;
console.log('\nFree (price=0) games among top-'+N+' most owned:', freeTopOwners);

